import java.nio.ByteBuffer
import java.nio.ByteOrder

class TH08HumidityDriver : Driver {
    override fun decode(frame: ByteArray): Double? {
        if (frame.size != 2) return null
        val raw = (frame[0].toInt() and 0xFF) or ((frame[1].toInt() and 0xFF) shl 8)
        if (raw > 10000) return null
        return raw / 100.0
    }
}
